families.bracket-fixed-join:
"""families.bracket-fixed-join: exact checks, ported from legacy verify_T13.py (prop:condensation) and
widened with composites whose mass is computed from the grip (twistor core over GA.QI).

lam = Lambda/6.
  (1) |B_Lambda|^2 = m^2/2 - Lambda C/6 = (Lambda/6)(nu^2 + 9/4 - C) as a rational-function identity in a
      formal Lambda (GA.RF), with m^2 = (nu^2 + 9/4) Lambda/3, at rational nu and C.
  (2) On composites (grip norm m^2, internal Casimir C) at three Lambda: |B|^2 = m^2/2 - Lambda C/6.
  (3) B_Lambda != 0 exactly when m^2 > Lambda C/3 (pairs with B != 0, doubled and massless composites
      with B = 0 as the other side).
  (4) The flat bracket differs from B_Lambda by the Lambda-suppressed omega-area (Lambda/6)[omega1 omega2].
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

# ---------------------------------------------------------------------------
# Twistor core (shared text, ported from legacy/verify_T11.py Parts B-D; self-contained).
# CS = C^4 with basis e1, e2 (omega-plane) and e3, e4 (pi-plane); the ambient space is
# Lambda^2 CS in the basis e_i ^ e_j (i < j), with n_inf = e1^e2, n_0 = e3^e4 and the pairing
# <P, P'> = coefficient of e1^e2^e3^e4 in P ^ P'. Everything is over the Gaussian rationals GA.QI.
# ---------------------------------------------------------------------------
from itertools import combinations as _comb

QZ = GA.qi(0)
QO = GA.qi(1)
PAIRS4 = list(_comb(range(4), 2))


def q(re, im=0):
    return GA.qi(re, im)


def eps2(a, b):
    """<ab> = a_0 b_1 - a_1 b_0."""
    return a[0] * b[1] - a[1] * b[0]


def wedge2(z1, z2):
    return [z1[i] * z2[j] - z1[j] * z2[i] for (i, j) in PAIRS4]


def perm_sign(perm):
    s, p = 1, list(perm)
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                s = -s
    return s


def amb_pair(P, R):
    tot = QZ
    for a, (i, j) in enumerate(PAIRS4):
        if not P[a]:
            continue
        for b, (k, l) in enumerate(PAIRS4):
            if R[b] and len({i, j, k, l}) == 4:
                tot = tot + q(perm_sign((i, j, k, l))) * P[a] * R[b]
    return tot


def biv(i, j):
    out = [QZ] * 6
    out[PAIRS4.index((min(i, j), max(i, j)))] = QO if i < j else -QO
    return out


def vadd(*us):
    return [sum((u[k] for u in us), QZ) for k in range(len(us[0]))]


def vscal(c, u):
    return [c * a for a in u]


N_INF, N_0 = biv(0, 1), biv(2, 3)
EAMB = [biv(i, j) for (i, j) in PAIRS4]
X_SLOT = [biv(0, 2), biv(0, 3), biv(1, 2), biv(1, 3)]


def twistor(om, pi):
    return [om[0], om[1], pi[0], pi[1]]


def i_lam(lam):
    """I = n_inf + lam n_0 (lam = Lambda/6)."""
    return vadd(N_INF, vscal(q(lam), N_0))


def xslot(co):
    return vadd(*[vscal(q(c), v) for c, v in zip(co, X_SLOT)])


def xpoint(x):
    """X(x) = n_0 + x - (1/2) <x,x> n_inf."""
    return vadd(N_0, x, vscal(-amb_pair(x, x) / q(2), N_INF))


def on_line(co, pi):
    """The twistor (mu_x pi, pi) on the incidence line of x = (x13, x14, x23, x24)."""
    x13, x14, x23, x24 = co
    om = [-q(x13) * pi[1] + q(x14) * pi[0], -q(x23) * pi[1] + q(x24) * pi[0]]
    return twistor(om, pi)


def act(A, P):
    """A.(u^v) = Au^v + u^Av, extended linearly to bivectors."""
    out = [QZ] * 6
    for a, (i, j) in enumerate(PAIRS4):
        if not P[a]:
            continue
        Aei = [A[r][i] for r in range(4)]
        Aej = [A[r][j] for r in range(4)]
        ei = [QO if r == i else QZ for r in range(4)]
        ej = [QO if r == j else QZ for r in range(4)]
        out = vadd(out, vscal(P[a], vadd(wedge2(Aei, ej), wedge2(ei, Aej))))
    return out


def rot(U, V, W):
    """R_{U^V}(W) = <U,W> V - <V,W> U."""
    return vadd(vscal(amb_pair(U, W), V), vscal(-amb_pair(V, W), U))


def gsolve(rows, rhs):
    """Exact solution of a consistent (possibly overdetermined) system over Q(i)."""
    m, n = len(rows), len(rows[0])
    A = [rows[i][:] + [rhs[i]] for i in range(m)]
    piv, r = [], 0
    for c in range(n):
        p = next((i for i in range(r, m) if A[i][c]), None)
        if p is None:
            continue
        A[r], A[p] = A[p], A[r]
        inv = QO / A[r][c]
        A[r] = [x * inv for x in A[r]]
        for i in range(m):
            if i != r and A[i][c]:
                f = A[i][c]
                A[i] = [x - f * y for x, y in zip(A[i], A[r])]
        piv.append(c)
        r += 1
    if any(A[i][n] for i in range(r, m)):
        raise ValueError("inconsistent linear system")
    if len(piv) != n:
        raise ValueError("underdetermined linear system")
    sol = [QZ] * n
    for i, c in enumerate(piv):
        sol[c] = A[i][n]
    return sol


_UNIT_ACT = []


def _unit_act():
    if not _UNIT_ACT:
        for r in range(4):
            for c in range(4):
                A = [[QZ] * 4 for _ in range(4)]
                A[r][c] = QO
                _UNIT_ACT.append([act(A, EAMB[b]) for b in range(6)])
    return _UNIT_ACT


_SP = {}


def spin_preimage(U, V):
    """The traceless A in gl(4) whose action on Lambda^2 CS is the rotation R_{U^V} (memoised)."""
    key = tuple((c.re, c.im) for c in U + V)
    if key not in _SP:
        _SP[key] = _spin_preimage(U, V)
    return [row[:] for row in _SP[key]]


def _spin_preimage(U, V):
    ua = _unit_act()
    rows, rhs = [], []
    for b in range(6):
        target = rot(U, V, EAMB[b])
        for comp in range(6):
            rows.append([ua[k][b][comp] for k in range(16)])
            rhs.append(target[comp])
    rows.append([QO if r == c else QZ for r in range(4) for c in range(4)])
    rhs.append(QZ)
    sol = gsolve(rows, rhs)
    return [[sol[4 * r + c] for c in range(4)] for r in range(4)]


SIG = [[QO if abs(a - b) == 2 else QZ for b in range(4)] for a in range(4)]


def herm(zi, zj):
    """conj(zi)^T Sigma zj: the (2,2) Hermitian form pairing omega with conj(pi)."""
    return sum((zi[a].conj() * zj[b] for a in range(4) for b in range(4) if SIG[a][b]), QZ)


def moment(A, Zs):
    """M_A = i sum_i conj(Z_i)^T Sigma A Z_i."""
    tot = QZ
    for z in Zs:
        Az = [sum((A[r][c] * z[c] for c in range(4)), QZ) for r in range(4)]
        tot = tot + herm(z, Az)
    return GA.QI_I * tot


def gram_inverse(basis):
    n = len(basis)
    Gs = [[amb_pair(u, v) for v in basis] for u in basis]
    cols = [gsolve([row[:] for row in Gs], [QO if r == c else QZ for r in range(n)]) for c in range(n)]
    return [[cols[c][r] for c in range(n)] for r in range(n)]


_GI = []


def grip(Zs, I):
    """P = M(I): the ambient vector with <P, U> = M_{A(U ^ I)} for every U."""
    if not _GI:
        _GI.append(gram_inverse(EAMB))
    vals = [moment(spin_preimage(EAMB[a], I), Zs) for a in range(6)]
    P = [sum((vals[a] * _GI[0][a][J] for a in range(6)), QZ) for J in range(6)]
    assert all(amb_pair(P, EAMB[a]) == vals[a] for a in range(6))
    return P


def gram_h(Zs):
    return [[herm(a, b) for b in Zs] for a in Zs]


def internal_casimir(Z1, Z2):
    """C = (h11 - h22)^2/4 + |h12|^2 = tr(h_0^2)/2."""
    h11, h22, h12 = herm(Z1, Z1), herm(Z2, Z2), herm(Z1, Z2)
    return (h11 - h22) * (h11 - h22) / q(4) + h12 * h12.conj()


def casimir(Zs, basis):
    """C2(W) = (1/2) g^{ac} g^{bd} M_ab M_cd over the span of `basis`."""
    n = len(basis)
    Gi = gram_inverse(basis)
    Mm = [[moment(spin_preimage(u, v), Zs) if a != b else QZ for b, v in enumerate(basis)]
          for a, u in enumerate(basis)]
    tot = QZ
    for a in range(n):
        for b in range(n):
            if not Mm[a][b]:
                continue
            for c in range(n):
                if not Gi[a][c]:
                    continue
                for d in range(n):
                    if Gi[b][d] and Mm[c][d]:
                        tot = tot + Gi[a][c] * Gi[b][d] * Mm[a][b] * Mm[c][d]
    return tot / q(2)


def xreal(t, x_, y, z):
    """The real slice x = i K eps, K the Hermitian matrix of (t, x, y, z)."""
    K = [[q(t + z), q(x_, -y)], [q(x_, y), q(t - z)]]
    eps = [[QZ, QO], [-QO, QZ]]
    X = [[sum((K[a][b] * eps[b][c] for b in range(2)), QZ) * GA.QI_I for c in range(2)] for a in range(2)]
    return vadd(*[vscal(c_, v) for c_, v in zip((X[0][0], X[0][1], X[1][0], X[1][1]), X_SLOT)])


def in_su22(A):
    SA = [[sum((SIG[i][k] * A[k][j] for k in range(4)), QZ) for j in range(4)] for i in range(4)]
    return all(SA[i][j] + SA[j][i].conj() == QZ for i in range(4) for j in range(4))

TW = [
    ([q(1), q(0)], [q(0), q(1)]),
    ([q(2, 1), q(0)], [q(1), q(1, -1)]),
    ([q(0), q(1, 1)], [q(3), q(2)]),
    ([q(1), q(2)], [q(1, 2), q(-1)]),
    ([q(1, -1), q(2, 1)], [q(0, 1), q(1, 1)]),
]
NU_C = [(F(7, 2), F(0)), (F(7, 2), F(1)), (F(1000), F(5, 3)), (F(1, 3), F(2))]
LAMS = [F(1, 2), F(2), F(1, 9)]


def check_fixed_bracket_identity_in_lambda():
    premise("families.imported-dictionary-exact-join")
    Lam = GA.RF.var()
    ok = True
    for nu, C in NU_C:
        m2 = GA.RF.const(nu * nu + F(9, 4)) * Lam / GA.RF.const(3)
        lhs = m2 / GA.RF.const(2) - Lam * GA.RF.const(C) / GA.RF.const(6)
        rhs = Lam / GA.RF.const(6) * GA.RF.const(nu * nu + F(9, 4) - C)
        ok = ok and lhs.eqrf(rhs)
    # hand value: nu = 7/2, C = 1 at Lambda = 6: |B|^2 = 49/4 + 9/4 - 1 = 27/2
    ok = ok and (F(6) / 6) * (F(49, 4) + F(9, 4) - 1) == F(27, 2)
    GA.check("|B|^2 = m^2/2 - Lambda C/6 = (Lambda/6)(nu^2 + 9/4 - C)", ok)
    assert ok


def check_bracket_from_composites():
    premise("families.imported-dictionary-exact-join")
    ok = True
    for i in range(5):
        for j in range(i + 1, 5):
            (o1, p1), (o2, p2) = TW[i], TW[j]
            Z1, Z2 = twistor(o1, p1), twistor(o2, p2)
            C = internal_casimir(Z1, Z2)
            for lam in LAMS:
                I = i_lam(lam)
                PL = grip([Z1, Z2], I)
                m2 = amb_pair(PL, PL)
                B = amb_pair(I, wedge2(Z1, Z2))
                Lam = q(6 * lam)
                ok = ok and B * B.conj() == m2 / q(2) - Lam * C / q(6)
                ok = ok and B - eps2(p1, p2) == q(lam) * eps2(o1, o2)
    GA.check("|B|^2 = m^2/2 - Lambda C/6 on composites; B - <pi1 pi2> = (Lambda/6)[omega1 omega2]", ok)
    assert ok


def check_bracket_nonzero_iff_mass_above_casimir_term():
    premise("families.imported-dictionary-exact-join")
    ok = True
    comps = [[twistor(*TW[0]), twistor(*TW[1])], [twistor(*TW[2]), twistor(*TW[4])],
             [twistor(*TW[1]), twistor(*TW[1])], [twistor(*TW[3]), twistor(*TW[3])],
             [[q(1), QZ, QZ, q(1)], [q(2), QZ, QZ, q(5)]]]
    sides = []
    for Zs in comps:
        for lam in LAMS:
            I = i_lam(lam)
            PL = grip(Zs, I)
            m2 = amb_pair(PL, PL).re
            C = internal_casimir(*Zs).re
            B = amb_pair(I, wedge2(*Zs))
            ok = ok and ((B != QZ) == (m2 > 6 * lam * C / 3))
            sides.append(B != QZ)
    ok = ok and sides.count(True) == 6 and sides.count(False) == 9
    GA.check("B_Lambda != 0 iff m^2 > Lambda C/3", ok)
    assert ok

families.doublet-direction-module-georgi:
"""families.doublet-direction-module-georgi-jarlskog-clebsch: exact checks.

The five-mode module Lambda(C^5) as 32 x 32 rational matrices (Jordan-Wigner, occupation basis; code modes
0, 1, 2 are the pair modes, 3, 4 the text's rung modes 4, 5), and in parallel the Clifford algebra of the ten
as GA's Cl(5,5): e_{2m} = v_m + w_m (square +1), e_{2m+1} = w_m - v_m (square -1), so v_m = (e_{2m} - e_{2m+1})/2
and w_m = (e_{2m} + e_{2m+1})/2. Grades are read off GA blades; the matrix image of every GA element used is
compared with the Jordan-Wigner operator built directly. B is the invariant pairing B(e_S, e_T) =
(-1)^(|S|(|S|-1)/2) eps(S, S^c) [T = S^c]; Y_T(psi, phi) = B(psi, T phi) on the sixteen (the even states).
(i) B - L = 1 - (2/3) N_W equals -(2/3) sum v_i ^ w_i (pure grade 2); w_4 chi = w_4 (1 - 2 n_5) = -2 w_4 (v_5 ^ w_5);
    T_GJ = w_4 (B - L) chi is pure grade 5 (no grade 1 or 3) and equals 4/3 of the grade-5 part of
    w_4 (v_5 ^ w_5) sum v_i ^ w_i. Of the two duality halves (1 +- omega)/2 T_GJ of the grade-5 element, both
    nonzero, one acts as zero on the sixteen (the 126bar half; that grade 5 on the sixteen is 126 + 126bar and
    that the surviving half is the 126 is the imported grade dictionary, not recomputed).
(ii) Species from (S): Y_{T_GJ} is symmetric, conserves hypercharge entry by entry ([Y, T_GJ] = -T_GJ/2),
    is nonzero exactly on (L, e^c) with entries {-1} and (Q, d^c) with entries {+1/3, -1/3}; Y_{w_4} has entries
    +-1 on the same pairs; |y_e / y_d| = 3 = |(B - L)(L) / (B - L)(Q)|.
(iii) Y_{w_4 (B - L)} is nonzero and antisymmetric, with (B - L)(L) + (B - L)(e^c) = 0 = (B - L)(Q) + (B - L)(d^c).
(iv) Y_{v_4 (B - L) chi} is symmetric, {+1} on (L, nu^c), {+1/3, -1/3} on (Q, u^c), and the sign on (Q, u^c)
    changes with the colour of the pair.
EXPORTS["module"] gives the construction to the claims that build on T_GJ.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# module construction (generic; nothing here is asserted)
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)
SPECIES = {(0, 0): "nuc", (2, 0): "uc", (1, 1): "Q", (3, 1): "L", (0, 2): "ec", (2, 2): "dc"}  # (N_W, N_R)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


def species(s):
    return SPECIES.get((nw(s), nr(s)))


def create(m):
    return fock.cre(m, NM)


def diag(fn):
    return fock.diag(fn, DIM)


# sparse exact operators from lib/fock.py (LSB order; comm and acomm are not halved); tr is the TRANSPOSE
tr = fock.transpose
mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
comm, acomm, meq = fock.comm, fock.acomm, fock.meq


ONE = fock.eye(DIM)
V = [create(m) for m in range(NM)]
W = [tr(v) for v in V]
NUM = [fock.num(m, NM) for m in range(NM)]
SIXTEEN = [s for s in range(DIM) if ntot(s) % 2 == 0]


def complement(s):
    return (DIM - 1) ^ s


def eps_sign(s):
    seq = [m for m in range(NM) if s >> m & 1] + [m for m in range(NM) if not s >> m & 1]
    return (-1) ** sum(1 for i in range(NM) for j in range(i + 1, NM) if seq[i] > seq[j])


def bcoef(s):
    k = bin(s).count("1")
    return F((-1) ** (k * (k - 1) // 2) * eps_sign(s))


def form(T):
    """Y_T(e_s, e_t) = B(e_s, T e_t) for s, t in the sixteen."""
    out = {}
    for s in SIXTEEN:
        for t in SIXTEEN:
            x = T.get((complement(s), t))
            if x:
                out[(s, t)] = bcoef(s) * x
    return out


def ftr(f):
    return {(t, s): x for (s, t), x in f.items()}


def fadd(*fs):
    return madd(*fs)


def sym(f):
    return msc(F(1, 2), madd(f, ftr(f)))


def clebsch(f):
    out = {}
    for (s, t), x in f.items():
        get_or_set(out, tuple(sorted((species(s), species(t)))), set()).add(x)
    return out


def op_weight(H, X):
    """c with [H, X] = c X, or None."""
    Y = comm(H, X)
    k = next(iter(X))
    c = Y.get(k, 0) / X[k]
    return c if meq(Y, msc(c, X)) else None


BL = diag(lambda s: 1 - F(2, 3) * nw(s))
CHI = diag(lambda s: -(-1) ** nr(s))
NW = diag(nw)
HYP = diag(lambda s: F(nr(s), 2) - F(nw(s), 3))
T3 = msc(F(1, 2), msub(NUM[3], NUM[4]))
SU3 = [mm(V[a], W[b]) for a in PAIRS for b in PAIRS if a != b] + [msub(NUM[0], NUM[1]), msub(NUM[1], NUM[2])]

# Clifford algebra of the ten in GA, signature (+,-) per mode
SQ = tuple([1, -1] * NM)
EMAT = [fock.majorana(p, NM) for p in range(2 * NM)]  # a_m^dag + a_m, a_m - a_m^dag


def gv(m):
    return {(2 * m,): F(1, 2), (2 * m + 1,): F(-1, 2)}


def gw(m):
    return {(2 * m,): F(1, 2), (2 * m + 1,): F(1, 2)}


def gmul(*xs):
    out = xs[0]
    for y in xs[1:]:
        out = GA.mul(out, y, SQ)
    return out


def gwedge2(a, b):
    return GA.scal(F(1, 2), GA.sub(gmul(a, b), gmul(b, a)))


def gnum(m):
    return gmul(gv(m), gw(m))


def grades(x):
    return sorted({len(b) for b in x})


def gpart(x, k):
    return {b: c for b, c in x.items() if len(b) == k}


def to_mat(x):
    out = {}
    for b, c in x.items():
        M = ONE
        for i in b:
            M = mm(M, EMAT[i])
        out = madd(out, msc(c, M))
    return out


def ga_BL():
    return GA.add(GA.sc(1), GA.scal(F(-2, 3), GA.add(*[gnum(i) for i in PAIRS])))


def ga_chi():
    return GA.neg(gmul(GA.sub(GA.sc(1), GA.scal(2, gnum(3))), GA.sub(GA.sc(1), GA.scal(2, gnum(4)))))


def ga_TGJ():
    return gmul(gw(3), ga_BL(), ga_chi())


def T_GJ():
    return mm(W[3], BL, CHI)


def T_GJ_up():
    return mm(V[3], BL, CHI)


def kernel(vecs):
    """Exact rank and kernel of a list of sparse vectors: returns (rank, [coefficient dicts c with sum c_i vecs_i = 0])."""
    piv, ker = [], []
    for i, v in enumerate(vecs):
        v = {k: x for k, x in v.items() if x}
        c = {i: F(1)}
        for key, pv, pc in piv:
            x = v.get(key)
            if x:
                v = madd(v, msc(-x, pv))
                c = madd(c, msc(-x, pc))
        if v:
            key = next(iter(v))
            x = v[key]
            piv.append((key, msc(1 / x, v), msc(1 / x, c)))
        else:
            ker.append(c)
    return len(piv), ker


def rank(vecs):
    return kernel(vecs)[0]


EXPORTS = {"module": {k: v for k, v in globals().items() if not k.startswith("_") and k not in ("GA", "F", "premise", "fock")}}


# ---------------------------------------------------------------------------
# checks
# ---------------------------------------------------------------------------

def check_t_gj_pure_grade_five():
    premise("families.imported-decomposition-grade-dictionary")
    pairbiv = GA.add(*[gwedge2(gv(i), gw(i)) for i in PAIRS])
    bl = ga_BL()
    ok = GA.eq(bl, GA.scal(F(-2, 3), pairbiv)) and grades(bl) == [2]
    # the GA model is the module: generators and B - L, chi agree with the Jordan-Wigner operators
    ok = ok and all(meq(to_mat(gv(m)), V[m]) and meq(to_mat(gw(m)), W[m]) for m in range(NM))
    ok = ok and meq(to_mat(bl), BL) and meq(to_mat(ga_chi()), CHI)
    # chi is +1 on the doublet sector N_R = 1, -1 on N_R = 0, 2
    ok = ok and all(CHI[(s, s)] == (1 if nr(s) == 1 else -1) for s in range(DIM))
    area5 = gwedge2(gv(4), gw(4))
    w4chi = gmul(gw(3), ga_chi())
    ok = ok and GA.eq(w4chi, gmul(gw(3), GA.sub(GA.sc(1), GA.scal(2, gnum(4)))))
    ok = ok and GA.eq(w4chi, GA.scal(-2, gmul(gw(3), area5)))
    t = ga_TGJ()
    ok = ok and grades(t) == [5] and gpart(t, 1) == {} and gpart(t, 3) == {}
